func:
// S2 – Étape 1 : décoder la trame brute et produire une mesure normalisée.
// Entrée : message du récepteur (ou de l'injecteur) sur pce92/uplink
//   { received_at, payload_hex, rssi, snr, source }
// Sortie 1 : mesure normalisée. Sortie 2 : trame rejetée.
const codec = global.get("codec");
if (!codec) {
    node.error("Codec S1 non chargé : ajouter codec dans functionGlobalContext (voir plateforme/flows/README.md)");
    node.status({ fill: "red", shape: "ring", text: "codec absent" });
    return null;
}

const entree = msg.payload || {};
const recuA = entree.received_at || new Date().toISOString(); // règle 4 : horodatage à la réception

function rejet(raison) {
    node.warn("Trame rejetée : " + raison);
    return [null, {
        topic: "pce92/evenements",
        payload: { type: "rejet", raison: raison, received_at: recuA,
                   payload_hex: entree.payload_hex || null, source: entree.source || null }
    }];
}

if (typeof entree.payload_hex !== "string") {
    return rejet("message sans payload_hex");
}
const hex = entree.payload_hex.replace(/\s+/g, "");
if (!/^[0-9a-fA-F]*$/.test(hex) || hex.length % 2 !== 0) {
    return rejet("payload_hex n'est pas de l'hexadécimal valide");
}

const octets = hex.match(/../g).map(h => parseInt(h, 16));
const res = codec.decodeUplink({ bytes: octets });
if (res.errors) {
    return rejet(res.errors.join(" ; "));
}

const d = res.data;
msg.topic = "pce92/mesures/" + d.node_id;
msg.payload = {
    node_id: d.node_id,
    received_at: recuA,
    water_mm: d.water_valid ? d.water_mm : null,  // null = mesure invalide (0xFFFF)
    water_valid: d.water_valid,
    batt_v: d.batt_v,                             // null = tension inconnue (0xFF)
    seq: d.seq,
    alert: d.alert,
    next_min: d.next_min,                         // null = inconnu (0xFF)
    expected_next_at: d.next_min === null ? null
        : new Date(Date.parse(recuA) + d.next_min * 60000).toISOString(),
    rssi: entree.rssi ?? null,
    snr: entree.snr ?? null,
    source: entree.source ?? null,
    payload_hex: hex.toUpperCase(),
    warnings: res.warnings
};
if (res.warnings.length) {
    node.warn("Nœud " + d.node_id + ", seq " + d.seq + " : " + res.warnings.join(" ; "));
}
node.status({ fill: d.alert ? "red" : "green", shape: "dot",
              text: "nœud " + d.node_id + " · seq " + d.seq + " · " + (d.water_valid ? d.water_mm + " mm" : "invalide") });
return [msg, null];

// S2 – Étape 2 : contrôler le compteur seq (règle 5 du contrat).
// Écart = (seq - dernier seq) modulo 65536, par nœud :
//   = 1          : trame normale ;
//   > 1          : trames perdues (la mesure est gardée) ;
//   = 0          : doublon (écarté) ;
//   > 32768      : la trame est plus ancienne que la dernière reçue. Trois cas :
//     - seq déjà reçu, trame identique        -> doublon en retard (écarté) ;
//     - seq compté comme perdu                 -> trame reçue en retard : elle n'est pas
//       publiée comme mesure actuelle (son heure de mesure est inconnue en v1.2 :
//       annexe A, une ancienne mesure ne doit pas déclencher d'alerte nouvelle). Elle est
//       gardée dans le journal des événements, et retirée du compte des pertes ;
//     - sinon                                   -> retour en arrière du compteur
//       (redémarrage du nœud) : la mesure est gardée, la mémoire du nœud repart de zéro.
// Mémoire par nœud : le dernier seq, les MEMOIRE derniers seq reçus (avec leur trame)
// et les seq perdus récents. Elle repart de zéro au redémarrage de Node-RED.
// Sortie 1 : mesure acceptée. Sortie 2 : événement.
const MEMOIRE = 64;
const m = msg.payload;
const cle = "seq_" + m.node_id;
const etat = flow.get(cle);
const precedent = etat ? etat.dernier : undefined;
const ecart = etat ? (m.seq - precedent + 65536) % 65536 : null;

function evenement(type, details) {
    return {
        topic: "pce92/evenements",
        payload: Object.assign({ type: type, node_id: m.node_id, seq: m.seq, received_at: m.received_at }, details)
    };
}

// Garde la trame reçue en mémoire (les MEMOIRE plus récentes).
function retenir(e) {
    e.recus[m.seq] = m.payload_hex;
    e.ordre.push(m.seq);
    while (e.ordre.length > MEMOIRE) delete e.recus[e.ordre.shift()];
}

// 1. Première trame de ce nœud depuis le démarrage de Node-RED : pas de contrôle possible.
if (!etat) {
    const e = { dernier: m.seq, dernier_recu_a: m.received_at, next_min: m.next_min, recus: {}, ordre: [], perdus: [] };
    retenir(e);
    flow.set(cle, e);
    m.seq_gap = null;
    m.lost_before = 0;
    node.status({ fill: "green", shape: "dot", text: "nœud " + m.node_id + " · seq " + m.seq });
    return [msg, null];
}

// 2. Doublon immédiat (même seq que la dernière trame).
if (ecart === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "doublon écarté · nœud " + m.node_id + " · seq " + m.seq });
    return [null, evenement("doublon", { en_retard: false })];
}

// 3. Trame plus ancienne que la dernière reçue.
if (ecart > 32768) {
    const retard = (precedent - m.seq + 65536) % 65536;   // en nombre de trames
    if (etat.recus[m.seq] !== undefined && etat.recus[m.seq] === m.payload_hex) {
        node.status({ fill: "yellow", shape: "ring", text: "doublon en retard écarté · nœud " + m.node_id + " · seq " + m.seq });
        return [null, evenement("doublon", { en_retard: true, retard_trames: retard })];
    }
    const i = etat.perdus.indexOf(m.seq);
    if (i >= 0) {
        etat.perdus.splice(i, 1);
        retenir(etat);
        flow.set(cle, etat);
        // Heure de mesure estimée : le contrat v1.2 ne la transmet pas. On la reconstruit à partir
        // de la dernière trame reçue et de la période (next_min), comme le propose l'annexe A.
        const periode = (etat.next_min || m.next_min || 30) * 60000;
        const estimee = new Date(Date.parse(etat.dernier_recu_a) - retard * periode).toISOString();
        node.status({ fill: "blue", shape: "ring", text: "trame en retard · nœud " + m.node_id + " · seq " + m.seq });
        return [null, evenement("trame_en_retard", {
            retard_trames: retard, mesure_estimee_a: estimee,
            water_mm: m.water_mm, water_valid: m.water_valid, batt_v: m.batt_v, alert: m.alert
        })];
    }
    // Redémarrage du nœud : la mémoire repart de cette trame.
    const e = { dernier: m.seq, dernier_recu_a: m.received_at, next_min: m.next_min, recus: {}, ordre: [], perdus: [] };
    retenir(e);
    flow.set(cle, e);
    m.seq_gap = ecart;
    m.lost_before = 0;
    node.status({ fill: "yellow", shape: "dot", text: "compteur revenu en arrière · nœud " + m.node_id + " · seq " + m.seq });
    return [msg, evenement("retour_seq", { seq_precedent: precedent })];
}

// 4. Trame normale (écart 1) ou trames perdues juste avant (écart > 1).
let evt = null;
m.seq_gap = ecart;
m.lost_before = ecart - 1;
if (m.lost_before > 0) {
    evt = evenement("trames_perdues", { nombre: m.lost_before, seq_precedent: precedent });
    for (let k = 1; k <= m.lost_before; k++) etat.perdus.push((precedent + k) % 65536);
    // On ne garde que les pertes récentes (au plus MEMOIRE trames derrière la dernière).
    etat.perdus = etat.perdus.filter(s => (m.seq - s + 65536) % 65536 <= MEMOIRE);
}
etat.dernier = m.seq;
etat.dernier_recu_a = m.received_at;
etat.next_min = m.next_min;
retenir(etat);
flow.set(cle, etat);
node.status({ fill: m.lost_before ? "yellow" : "green", shape: "dot",
              text: "nœud " + m.node_id + " · seq " + m.seq + (m.lost_before ? " · " + m.lost_before + " perdue(s)" : "") });
return [msg, evt];
